package local.tvmorph.tv;
import org.json.*;import java.net.*;import java.io.*;import java.util.*;import java.util.regex.*;
/** Generic channel M3U source. Stream addresses remain native, resolved by stable ID. */
final class M3uPlaylist{
 static final String PUBLIC_URL="https://iptv-org.github.io/iptv/languages/ara.m3u";
 static String publicSource(JSONObject c){String key=c.optString("publicSource","");if(Arrays.asList("arabic","arab-region","news").contains(key))return key;String url=c.optString("server");return url.equals(publicUrl("news"))?"news":url.equals(publicUrl("arab-region"))?"arab-region":"arabic";}
 static String publicUrl(String key){return "https://iptv-org.github.io/iptv/"+(key.equals("arab-region")?"regions/arab.m3u":key.equals("news")?"categories/news.m3u":"languages/ara.m3u");}
 interface LocalFiles{InputStream open(String id)throws Exception;}static volatile LocalFiles localFiles;
 final JSONObject config;private JSONArray rows;private final Map<String,String> streams=new LinkedHashMap<>();private long loaded;
 M3uPlaylist(JSONObject value)throws Exception{config=normalize(value);}
 static JSONObject normalize(JSONObject input)throws Exception{JSONObject c=new JSONObject(input.toString());String source=publicSource(c);String url=c.optBoolean("publicMode")?publicUrl(source):c.optString("server","").trim();if(c.optBoolean("publicMode"))c.put("publicSource",source);valid(url);c.put("type","m3u").put("server",url).put("username","").put("password","").put("live",true).put("vod",false).put("series",false).put("format","m3u8");return c;}
 static URI valid(String s)throws Exception{URI u=new URI(s);if(u.getRawAuthority()!=null&&(u.getRawAuthority().contains(",")||u.getRawAuthority().contains("،")))throw new IOException("راجع عنوان السيرفر: استخدم نقطة (.) بدل الفاصلة (,).");if(s.length()>4000||!Arrays.asList("http","https").contains(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null)throw new IOException("اكتب رابط M3U كاملًا مع http أو https.");return u;}
 static String id(String value){long h=2166136261L,j=2166136261L;for(int n=0;n<value.length();n++){h=((h^value.charAt(n))*16777619L)&0xffffffffL;j=((j^value.charAt(n))*2246822519L)&0xffffffffL;}return Long.toString(h*4096+(j>>>20));}
 static String attr(String line,String name){Matcher m=Pattern.compile("(?:^|\\s)"+Pattern.quote(name)+"\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s,]+))",Pattern.CASE_INSENSITIVE).matcher(line);return m.find()?(m.group(1)!=null?m.group(1):m.group(2)!=null?m.group(2):m.group(3)):"";}
 static int comma(String s){char quote=0;for(int i=0;i<s.length();i++){char c=s.charAt(i);if(quote!=0){if(c==quote)quote=0;}else if(c=='\''||c=='"')quote=c;else if(c==',')return i;}return -1;}
 static String limitedLine(BufferedReader reader)throws IOException{StringBuilder line=new StringBuilder();int c;while((c=reader.read())!=-1){if(c=='\n')break;if(line.length()>=65536)throw new IOException("سطر M3U أطول من الحد المسموح.");line.append((char)c);}return c==-1&&line.length()==0?null:line.toString();}
 synchronized void parse(String body,String base)throws Exception{parseReader(new BufferedReader(new StringReader(body)),base,Long.MAX_VALUE);}
 synchronized void parseReader(BufferedReader reader,String base,long deadline)throws Exception{JSONArray next=new JSONArray();Map<String,String> addresses=new LinkedHashMap<>();String meta="",group="";URI root=valid(base);
 String raw;boolean header=false;long chars=0;while((raw=limitedLine(reader))!=null){chars+=raw.length()+1;if(chars>96L*1024*1024)throw new IOException("قائمة M3U تجاوزت الحد الآمن (96 MB). استخدم ربط Xtream أو قائمة أصغر.");if(raw.length()>65536)throw new IOException("سطر M3U أطول من الحد المسموح.");if(Thread.currentThread().isInterrupted()||System.nanoTime()>deadline)throw new IOException("انتهت مهلة تحميل القائمة. أعد المحاولة.");String line=raw.replace("\ufeff", "").trim();if(line.isEmpty())continue;if(!header){if(!line.startsWith("#EXTM3U"))throw new IOException("الرابط مش قائمة M3U صالحة.");header=true;continue;}if(line.startsWith("#EXT-X-TARGETDURATION")||line.startsWith("#EXT-X-STREAM-INF"))throw new IOException("استخدم رابط قائمة القنوات، مش رابط بث قناة واحدة.");if(line.startsWith("#EXTINF:")){meta=line;group=attr(meta,"group-title");}else if(line.startsWith("#EXTGRP:")){group=line.substring(8).trim();}else if(!line.isEmpty()&&!line.startsWith("#")){String address;try{if(!config.optString("localFileId").isEmpty()&&!new URI(line).isAbsolute())throw new IOException("Absolute HTTP media URLs required");address=root.resolve(line).toString();valid(address);}catch(Exception bad){meta="";group="";continue;}String key=id(address);if(addresses.containsKey(key)){meta="";group="";continue;}int split=comma(meta);String name=split>=0?meta.substring(split+1).trim():attr(meta,"tvg-name");if(name.isEmpty())name="Channel "+(next.length()+1);String icon=attr(meta,"tvg-logo");try{if(!icon.isEmpty()){icon=root.resolve(icon).toString();valid(icon);}}catch(Exception bad){icon="";}if(group.isEmpty())group="General";String category=id(group);next.put(new JSONObject().put("id",key).put("kind","live").put("name",name.substring(0,Math.min(250,name.length()))).put("icon",icon).put("category",category).put("group",group.substring(0,Math.min(160,group.length()))).put("ext","m3u8"));addresses.put(key,address);meta="";group="";if(next.length()>100000)throw new IOException("القائمة تجاوزت 100000 قناة. استخدم ربط Xtream أو قائمة أصغر.");}}
 if(next.length()==0)throw new IOException("القائمة مفيهاش روابط قنوات HTTP صالحة.");rows=next;streams.clear();streams.putAll(addresses);loaded=System.currentTimeMillis();}

 synchronized void ensure()throws Exception{if(rows!=null&&System.currentTimeMillis()-loaded<600000)return;String local=config.optString("localFileId");if(!local.isEmpty()){if(localFiles==null)throw new IOException("ملف القائمة غير متاح في هذه النسخة.");try(BufferedReader reader=new BufferedReader(new InputStreamReader(localFiles.open(local),"UTF-8"),16384)){parseReader(reader,config.getString("server"),System.nanoTime()+90000000000L);}return;}String url=config.getString("server");long deadline=System.nanoTime()+90000000000L;for(int redirects=0;redirects<=5;redirects++){valid(url);HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();try{c.setConnectTimeout(8000);c.setReadTimeout(10000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Morph TV M3U");c.setRequestProperty("Accept-Encoding","gzip");int status=c.getResponseCode();if(Arrays.asList(301,302,303,307,308).contains(status)){String location=c.getHeaderField("Location");if(location==null)throw new IOException("رابط تحويل القائمة غير صالح.");url=new URI(url).resolve(location).toString();continue;}if(status!=200)throw new IOException("تعذر تحميل قائمة M3U (HTTP "+status+").");InputStream stream=c.getInputStream();if("gzip".equalsIgnoreCase(c.getContentEncoding()))stream=new java.util.zip.GZIPInputStream(stream);try(BufferedReader reader=new BufferedReader(new InputStreamReader(stream,"UTF-8"),16384)){parseReader(reader,url,deadline);}return;}finally{c.disconnect();}}throw new IOException("تعذّر تحميل قائمة M3U. راجع الرابط والإنترنت.");}
 synchronized void clear(){rows=null;streams.clear();loaded=0;}
 JSONObject auth()throws Exception{ensure();return new JSONObject().put("connected",true).put("name",config.optString("name","M3U")).put("type","m3u").put("live",true).put("vod",false).put("series",false).put("channels",rows.length());}
 JSONArray categories(String kind)throws Exception{ensure();JSONArray out=new JSONArray();if(!kind.equals("live"))return out;Set<String> seen=new LinkedHashSet<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(seen.add(r.getString("category")))out.put(new JSONObject().put("category_id",r.getString("category")).put("category_name",r.getString("group")));}return out;}
 JSONArray list(String kind,String category)throws Exception{ensure();JSONArray out=new JSONArray();if(!kind.equals("live"))return out;for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(category.isEmpty()||category.equals(r.getString("category")))out.put(new JSONObject(r.toString()));}return out;}
 String stream(JSONObject item)throws Exception{ensure();String value=streams.get(item.optString("id"));if(!"live".equals(item.optString("kind"))||value==null)throw new IOException("اختار قناة من القائمة الحالية.");return value;}
}
